solution.solution.cpp:
#include <array>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct CodeView { std::array<std::uint8_t, 16> guid; std::uint32_t age; std::string path; };

std::optional<CodeView> parseCodeView(const std::vector<std::uint8_t>& record)
{
    if (record.size() < 24 || record[0] != 'R' || record[1] != 'S' || record[2] != 'D' || record[3] != 'S') return std::nullopt;
    CodeView cv{};
    for (int i{ 0 }; i < 16; ++i) cv.guid[i] = record[4 + i];
    cv.age = record[20] | (record[21] << 8) | (record[22] << 16) | (static_cast<std::uint32_t>(record[23]) << 24);
    for (std::size_t i{ 24 }; i < record.size() && record[i] != 0; ++i) cv.path += static_cast<char>(record[i]);
    return cv;
}

std::string pdbName(const std::string& path)
{
    const std::size_t slash{ path.find_last_of("\\/") };
    return slash == std::string::npos ? path : path.substr(slash + 1);
}

static std::string hex(std::uint64_t value, int digits)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    std::string out;
    for (int i{ digits - 1 }; i >= 0; --i) out += HEX[(value >> (4 * i)) & 0xF];
    return out;
}

std::string guidText(const std::array<std::uint8_t, 16>& g)
{
    const std::uint32_t d1{ g[0] | (g[1] << 8) | (g[2] << 16) | (static_cast<std::uint32_t>(g[3]) << 24) };
    const std::uint16_t d2{ static_cast<std::uint16_t>(g[4] | (g[5] << 8)) }, d3{ static_cast<std::uint16_t>(g[6] | (g[7] << 8)) };
    std::string out{ hex(d1, 8) + hex(d2, 4) + hex(d3, 4) };
    for (int i{ 8 }; i < 16; ++i) out += hex(g[i], 2);
    return out;
}

std::string symbolServerPath(const CodeView& cv)
{
    std::string age;
    std::uint32_t a{ cv.age };
    do { age.insert(age.begin(), "0123456789ABCDEF"[a & 0xF]); a >>= 4; } while (a);
    const std::string name{ pdbName(cv.path) };
    return name + "/" + guidText(cv.guid) + age + "/" + name;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
// GUID {3F2504E0-4F89-11D3-9A0C-0305E82C3301}, age 1, as the linker stores it
static Bytes record(std::uint32_t age = 1)
{
    Bytes b{ 'R', 'S', 'D', 'S', 0xE0, 0x04, 0x25, 0x3F, 0x89, 0x4F, 0xD3, 0x11, 0x9A, 0x0C, 0x03, 0x05, 0xE8, 0x2C, 0x33, 0x01 };
    for (int i{ 0 }; i < 4; ++i) b.push_back(static_cast<std::uint8_t>(age >> (8 * i)));
    for (char c : std::string("C:\\src\\Inventory\\x64\\Release\\Inventory.pdb")) b.push_back(static_cast<std::uint8_t>(c));
    b.push_back(0);
    return b;
}

TEST("parsing the record") {
    const auto cv{ parseCodeView(record()) };
    CHECK(cv.has_value());
    if (!cv) return;
    CHECK_EQ(cv->age, 1u);
    CHECK_EQ(cv->guid[0], 0xE0);
    CHECK_EQ(cv->path, std::string("C:\\src\\Inventory\\x64\\Release\\Inventory.pdb"));
    CHECK(!parseCodeView(Bytes(10, 0)).has_value());
    Bytes nb10{ record() }; nb10[0] = 'N';
    CHECK(!parseCodeView(nb10).has_value());
}
TEST("names") {
    CHECK_EQ(pdbName("C:\\src\\Inventory.pdb"), std::string("Inventory.pdb"));
    CHECK_EQ(pdbName("/build/out/game.pdb"), std::string("game.pdb"));
    CHECK_EQ(pdbName("plain.pdb"), std::string("plain.pdb"));
}
TEST("the GUID as text") {
    const auto cv{ parseCodeView(record()) };
    if (!cv) { CHECK(false); return; }
    CHECK_EQ(guidText(cv->guid), std::string("3F2504E04F8911D39A0C0305E82C3301"));
}
TEST("symbol server paths") {
    const auto one{ parseCodeView(record(1)) };
    const auto big{ parseCodeView(record(0x2A)) };
    if (!one || !big) { CHECK(false); return; }
    CHECK_EQ(symbolServerPath(*one), std::string("Inventory.pdb/3F2504E04F8911D39A0C0305E82C33011/Inventory.pdb"));
    CHECK_EQ(symbolServerPath(*big), std::string("Inventory.pdb/3F2504E04F8911D39A0C0305E82C33012A/Inventory.pdb"));
}

